const east = 6;
const north = 5;
const blocked = new Set(["4,3"]);
const run = (fromX, fromY, toX, toY) => {
  const grid = [];
  for (let x = fromX; x <= toX; x++) {
    grid[x] = [];
    for (let y = fromY; y <= toY; y++) {
      if (blocked.has(`${x},${y}`)) {
        grid[x][y] = 0;
      } else if (x === fromX && y === fromY) {
        grid[x][y] = 1;
      } else {
        const left = x > fromX ? grid[x - 1][y] : 0;
        const below = y > fromY ? grid[x][y - 1] : 0;
        grid[x][y] = left + below;
      }
    }
  }
  return grid[toX][toY];
};
return run(0, 0, east, north);
